    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // Scalar parameter for the current "diagonal distance" d = j - i
    Param<int> d_param("d_param");

    // Bind the buffers once; we update 'table' in-place on the host,
    // and Halide will always read the up-to-date values from it.
    seq_param.set(seq);
    table_param.set(table);

    // ------------------------------------------------------------------
    // Optimized Halide kernel: compute one entire diagonal (fixed d = j-i)
    // of the DP table in a single realization.
    //
    // We exploit the fact that Nussinov DP dependencies are only on
    // *shorter* intervals (smaller j-i), so all cells with the same
    // interval length d can be computed independently of each other.
    //
    // Standard recurrence (for i < j):
    //
    //   best = max(best, table[i][j-1]);                     // left
    //   best = max(best, table[i+1][j]);                     // down
    //   best = max(best, table[i+1][j-1] + match(i,j));      // diag / pair
    //   for k = i+1 .. j-1:
    //     best = max(best, table[i][k] + table[k+1][j]);     // split
    //
    // where match(i,j) is 1 if bases pair (b_i + b_j == 3), else 0.
    //
    // We define a 1D Func over ii corresponding to i, with j = i + d.
    // For each fixed d, we realize diag(ii) for ii = 0..(n-d-1), then
    // write back diag(ii) into table[i][j].
    //
    // This keeps all DP dependencies intact while letting Halide
    // vectorize and parallelize along the diagonal.
    // ------------------------------------------------------------------

    Var ii("ii");      // index along the current diagonal (represents i)
    Func diag("diag");

    {
        // i = ii, j = i + d
        Expr i = ii;
        Expr j = ii + d_param;

        // Start from the current value in the table.
        // Initially table is zero everywhere, and each (i,j) is written
        // exactly once, so this is equivalent to starting from 0, but
        // keeping the read makes the recurrence faithful to the original.
        Expr best = table_param(j, i);  // table[i][j] -> table_param(j, i)

        // best = max(best, table[i][j-1]);
        best = max(best, table_param(j - 1, i));

        // best = max(best, table[i+1][j]);
        best = max(best, table_param(j, i + 1));

        // Diagonal / pairing term:
        //
        // In the original C code:
        //   if (i < j-1)
        //     best = max(best, table[i+1][j-1] + match(seq[i], seq[j]));
        //   else
        //     best = max(best, table[i+1][j-1]);
        //
        // Here we implement the same logic, using a conditional match_term.
        Expr b1 = cast<int32_t>(seq_param(i));
        Expr b2 = cast<int32_t>(seq_param(j));
        // match(b1,b2) = ((b1 + b2) == 3 ? 1 : 0)
        Expr match_val = select(b1 + b2 == 3, 1, 0);
        Expr match_term = select(i < j - 1,
                                 cast<num_t>(match_val),
                                 cast<num_t>(0));

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate = table_param(j - 1, i + 1) + match_term;
        best = max(best, diag_candidate);

        // Split term:
        //
        // for (k = i+1; k < j; k++)
        //   best = max(best, table[i][k] + table[k+1][j]);
        //
        // For fixed d, j-i = d, so k runs from i+1 to i+d-1.
        Expr extent = d_param - 1;          // j - i - 1 = d - 1
        RDom r(i + 1, extent, "r");         // r.x in [i+1, i+d-1], or empty if d==1

        // Pure definition: initialize diag(ii) with the "best" we have so far.
        diag(ii) = best;

        // Update definition: take the max over all k (r.x).
        diag(ii) = max(diag(ii),
                       table_param(r.x, i) + table_param(j, r.x + 1));
    }

    // ------------------------- Scheduling ------------------------------

    // We compute each diagonal as a 1D buffer and want good CPU usage.
    // We'll:
    //   - compute at root,
    //   - split the iteration space into tiles,
    //   - parallelize tiles across cores,
    //   - vectorize within each tile.
    const int vector_width = 8;   // reasonable default; Halide will handle tails
    const int tile_size    = 64;  // tile size in 'ii' for parallel work

    Var ii_outer("ii_outer"), ii_inner("ii_inner");
    Var ii_outer_u("ii_outer_u"), ii_inner_u("ii_inner_u");

    // Schedule the pure definition of diag
    diag.compute_root()
        .split(ii, ii_outer, ii_inner, tile_size)
        .parallel(ii_outer)
        .vectorize(ii_inner, vector_width);

    // Schedule the update (reduction) step of diag in the same way
    diag.update()
        .split(ii, ii_outer_u, ii_inner_u, tile_size)
        .parallel(ii_outer_u)
        .vectorize(ii_inner_u, vector_width);

    // JIT-compile the per-diagonal pipeline once.
    diag.compile_jit();

    // ------------------ Run the dynamic program ------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // Instead of row-wise (i,j) order, we compute in increasing
    // interval length d = j - i. For each d, all (i,j=i+d) are
    // independent and can be computed in a single Halide call.
    //
    // This order still respects all DP dependencies: every term in the
    // recurrence depends only on intervals with smaller length.
    for (int d = 1; d < n; ++d) {
        d_param.set(d);

        const int diag_len = n - d; // i = 0 .. n-d-1

        // Realize the entire diagonal into a 1D buffer.
        Halide::Buffer<num_t> diag_buf = diag.realize(diag_len);

        // Write back into the DP table:
        //   i = ii
        //   j = i + d
        // table[i][j] -> table(j, i)
        for (int i = 0; i < diag_len; ++i) {
            int j = i + d;
            table(j, i) = diag_buf(i);
        }
    }

    auto end      = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

