    Halide::Buffer<base_t, 1> seq(n);
    Halide::Buffer<num_t, 2>  table(n, n);

    // Initialize data
    init_array(n, seq, table);

    // ImageParams to expose the current state to Halide
    ImageParam seq_param(type_of<base_t>(), 1, "seq_param");
    ImageParam table_param(type_of<num_t>(), 2, "table_param");

    // Scalar parameter for the current diagonal distance d = j - i
    Param<int> d_param("d_param");

    // Bind the buffers once; we mutate 'table' in-place on the host,
    // and Halide will always read the up-to-date values from it.
    seq_param.set(seq);
    table_param.set(table);

    // --------------------------------------------------------------------
    // Optimized per-diagonal DP kernel:
    //
    // Instead of calling Halide once per (i,j) cell, we observe that
    // for the Nussinov recurrence every table[i][j] depends only on
    // entries with strictly smaller interval length (j - i).
    //
    // That means we can process the table by diagonals of constant
    // d = j - i, in increasing d, and compute the entire diagonal in
    // one Halide realization. Within a diagonal, all cells are
    // independent given the already-computed shorter intervals.
    //
    // This preserves the original DP semantics but drastically
    // reduces Halide overhead: we do O(n) Halide calls instead of
    // O(n^2), and each call computes O(n) cells in parallel.
    // --------------------------------------------------------------------

    Func diag("diag");   // diag(i) computes table[i][i + d_param] for current d_param
    Var  i("i");

    {
        // j is expressed in terms of i and the current diagonal distance d_param.
        Expr j = i + d_param;

        // Current value table[i][j]
        // (C: table[i][j] -> Halide: table_param(j, i))
        Expr best = table_param(j, i);

        // if (j-1 >= 0) table[i][j] = max(table[i][j], table[i][j-1]);
        // For all (i,j) on a valid diagonal with d = j-i >= 1, we have j >= 1,
        // so the condition is always true.
        best = max(best, table_param(j - 1, i));

        // if (i+1 < N) table[i][j] = max(table[i][j], table[i+1][j]);
        // For all (i,j) on valid diagonals with d >= 1, we have i <= N-2,
        // so i+1 < N always holds.
        best = max(best, table_param(j, i + 1));

        // Diagonal / pairing term:
        //
        // if (j-1 >= 0 && i+1 < N) {
        //   if (i < j-1)
        //     table[i][j] = max(table[i][j],
        //                        table[i+1][j-1] + match(seq[i], seq[j]));
        //   else
        //     table[i][j] = max(table[i][j], table[i+1][j-1]);
        // }
        //
        // Again, the outer bounds check is always true along valid diagonals.
        Expr b1 = cast<int32_t>(seq_param(i));
        Expr b2 = cast<int32_t>(seq_param(j));

        // match(b1,b2) = ((b1 + b2) == 3 ? 1 : 0)
        Expr match_val = select(b1 + b2 == 3, 1, 0);

        // Only allow bonding when i < j-1; otherwise, don't add match().
        Expr match_term = select(i < j - 1,
                                 cast<num_t>(match_val),
                                 cast<num_t>(0));

        // table[i+1][j-1] -> table_param(j-1, i+1)
        Expr diag_candidate = table_param(j - 1, i + 1) + match_term;
        best = max(best, diag_candidate);

        // Split term:
        //
        // for (k = i+1; k < j; k++)
        //   table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
        //
        // For a fixed diagonal distance d = j - i, k runs from i+1 to j-1,
        // i.e. there are (d - 1) split positions.
        Expr extent = max(d_param - 1, 0);   // number of ks; 0 for d=1
        RDom r(0, extent, "r");

        // Map r.x to the actual split index k.
        Expr k = i + 1 + r.x;

        // Pure definition: start from 'best'.
        diag(i) = best;

        // Reduction update: take the maximum over all splits k.
        // Note: diag is referenced only at (i), satisfying Halide's
        // restriction on reduction updates.
        diag(i) = max(diag(i),
                      table_param(k, i) + table_param(j, k + 1));
