    //  * parallel(i):    process independent cells of a diagonal in parallel
    //  * vectorize(i):   exploit SIMD within each diagonal
    // --------------------------------------------------------------------
    Target target = get_host_target();
    // Use a reasonable fixed vector width; Halide will handle tails.
    const int vec_width = 8;

    diag.compute_root()
        .parallel(i)
        .vectorize(i, vec_width);

    diag.update()
        .parallel(i)
        .vectorize(i, vec_width);

    // JIT-compile once.
    diag.compile_jit(target);

    // --------------------------------------------------------------------
    // Time the DP kernel (the diagonal loops plus Halide calls).
    // --------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Original kernel in row/column form:
    //
    // for (i = N-1; i >= 0; i--) {
    //   for (j = i+1; j < N; j++) {
    //     ... updates to table[i][j] ...
    //   }
    // }
    //
    // This is equivalent to iterating over diagonals of constant
    // distance d = j - i in increasing d, and then over i within each
    // diagonal:
    //
