    // strictly smaller distance (j - i), so this reordering preserves
    // the DP semantics but lets us compute an entire diagonal in one
    // Halide realization.

    for (int d = 1; d < n; ++d) {
        d_param.set(d);

        const int diag_len = n - d;  // number of (i,j) pairs on this diagonal

        // Compute the whole diagonal [ (i, j=i+d) for i in 0..diag_len-1 ].
        Halide::Buffer<num_t, 1> diag_out(diag_len);
        diag.realize(diag_out);

        // Scatter the results back into the 2D DP table.
        for (int i_host = 0; i_host < diag_len; ++i_host) {
            int j_host = i_host + d;
            // C: table[i][j] -> Halide: table(j, i)
            table(j_host, i_host) = diag_out(i_host);
        }
    }

    auto end      = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
